def title(name): return name.replace("_", " ").title().replace("Vsix", "VSIX").replace("Ai ", "AI ").replace("Ipc", "IPC").replace("Ci Cd", "CI/CD")

def standard(group, name):
    future = group == "web3" or "FUTURE" in name
    status = "RESEARCH — NOT IMPLEMENTED" if future else "FOUNDATION — NOT IMPLEMENTED"
    boundary = "This capability is optional future architecture and is not required for MVP or V1." if future else "This document defines a reviewable Phase 0 contract; it does not describe shipped behavior."
    return f"""# {title(name)}\n\n**Status: {status}.** {boundary}\n\n## Purpose\n\nDefine the {title(name).lower()} decisions needed to preserve local-first operation, evidence provenance, least privilege, privacy, reversibility, and honest public status.\n\n## Policy\n\n- Every input has a source, authorization scope, sensitivity class, and retention rule.\n- Every output distinguishes observed fact from inference and exposes limitations.\n- Network, execution, write, and persistence authority are separate grants.\n- Failures are explicit, observable, cancellable where possible, and never converted into false success.\n- Security and privacy tests are acceptance requirements, not post-release additions.\n\n## MVP and V1 boundary\n\nMVP includes only what is explicitly listed in `docs/product/MVP_SCOPE.md`. V1 follows `docs/product/V1_SCOPE.md`. Any broader behavior remains research until an ADR, threat review, requirements, and test plan are approved.\n\n## Open decisions\n\nOwner, measurable acceptance criteria, operational budget, supported matrix, abuse cases, and migration/rollback details must be resolved before implementation.\n"""

SPECS = ["GOLDENCORE","GOLDENGRAPH","GOLDENEYE","GOLDENGIT","GOLDENSHIELD","GOLDENFORGE","GOLDENMEMORY","GOLDENLAB","MODEL_GATEWAY","EVIDENCE_SYSTEM","PERMISSION_SYSTEM","LOCAL_RUNTIME","VS_CODE_CLIENT","AUTHENTICATION","PROJECT_DISCOVERY","INVESTIGATION_LIFECYCLE"]

def spec(name):
    display = title(name).replace("Goldencore","GoldenCore").replace("Goldengraph","GoldenGraph").replace("Goldeneye","GoldenEye").replace("Goldengit","GoldenGit").replace("Goldenshield","GoldenShield").replace("Goldenforge","GoldenForge").replace("Goldenmemory","GoldenMemory").replace("Goldenlab","GoldenLab")
    return f"""# {display} Specification\n\n**Status: foundation; not implemented.**\n\n## Contract\n\nPurpose: provide the bounded {display} responsibility within an evidence-backed investigation. It does not inherit filesystem, execution, network, write, or retention authority from another component.\n\nInputs are versioned, authorized envelopes with provenance and sensitivity. Outputs are typed results or explicit failures with correlation IDs. Dependencies are injected behind interfaces; persistence is local and minimal unless the product scope says otherwise.\n\n## Trust, permissions, and privacy\n\nTreat workspace/provider data as untrusted; canonicalize boundaries; redact secrets; enforce per-operation grants; minimize retained payloads; and emit content-safe audit events.\n\n## Failure and observability\n\nTimeout, cancellation, malformed input, stale evidence, partial availability, permission denial, dependency failure, and storage corruption must be distinguishable. Logs use structured metadata without raw sensitive content.\n\n## Testing and maturity\n\nContract, fixture, fault-injection, permission, privacy, and abuse-case tests precede integration. MVP/V1 inclusion is governed only by their scope documents; all other behavior is future research.\n"""

ADRS = ["MONOREPO","TYPESCRIPT_VSIX","PYTHON_RUNTIME","RUST_NATIVE_BOUNDARY","POSTGRES_CLOUD","SQLITE_LOCAL","LOCAL_FIRST","MODEL_GATEWAY","GITHUB_ACTIONS","BASE_EVM","SOLIDITY","FOUNDRY","SELECTIVE_BLOCKCHAIN","WEB3_NOT_MVP","VSIX_FIRST_CLIENT","REFERENCE_GOLDEN_AGENT","GRAPH_STORAGE","AUTH_BOUNDARY","LOCAL_IPC_SECURITY"]

def adr(i, name):
    future = name in {"RUST_NATIVE_BOUNDARY","BASE_EVM","SOLIDITY","FOUNDRY","SELECTIVE_BLOCKCHAIN","REFERENCE_GOLDEN_AGENT"}
    decision = title(name)
    return f"""# ADR-{i:04d}: {decision}\n\n- Status: Proposed\n- Date: 2026-08-10\n\n## Context\n\nGolden Apple needs a reviewable decision for {decision.lower()} while the repository contains no product implementation.\n\n## Decision\n\nAdopt this direction as {'research only; it creates no MVP dependency' if future else 'the Phase 0 default, subject to prototype validation before acceptance'}.\n\n## Alternatives considered\n\nA single-process product, a different technology, deferring the choice, and a managed/cloud-first design were considered. Detailed benchmarks remain outstanding.\n\n## Reasoning\n\nThe proposal best supports local-first control, narrow trust boundaries, portability, testability, and incremental delivery under current assumptions.\n\n## Consequences and risks\n\nThe decision adds integration and maintenance cost and may change after threat modeling, profiling, ecosystem research, or legal review. No implementation should treat a Proposed ADR as irreversible certainty.\n"""

def write(rel, body):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists(): path.write_text(body, encoding="utf-8")

for rel, body in FILES.items(): write(rel, body)
for group, names in GROUPS.items():
    for name in names: write(f"docs/{group}/{name}.md", standard(group, name))
for name in SPECS: write(f"specs/{name}.md", spec(name))
for i, name in enumerate(ADRS, 1): write(f"docs/adr/{i:04d}-{name.lower().replace('_','-')}.md", adr(i, name))
